UPDATE `quest_template_locale` SET `QuestDescription` = 'Ты так хорошо $gсправился:справилась; с лейтенантами и приспешниками, что я хочу дать тебе еще одно поручение.$B$BСерена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар. Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры.$B$BПерережь ей горло и принеси мне ее голову. Я хочу прибить ее на переднюю телегу следующего каравана... Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас.' WHERE `ID` = 876 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Ты так хорошо $gсправился:справилась; с лейтенантами и приспешниками, что я хочу дать тебе еще одно поручение.$B$BСерена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар. Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры.$B$BПерережь ей горло и принеси мне ее голову. Я хочу прибить ее на переднюю телегу следующего каравана... Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас.' AS BINARY)));
