UPDATE `quest_template_locale` SET `QuestDescription` = 'Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, |3-6($r). *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрестке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает*$B$BИмена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, |3-6($r), как они убили меня.' WHERE `ID` = 879 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, |3-6($r). *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрестке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает*$B$BИмена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, |3-6($r), как они убили меня.' AS BINARY)));
