UPDATE `quest_template_locale` SET `QuestDescription` = 'Быть может, тебе знакома мука неопределенности, а может, и нет. Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть. Быть может, мне стоило идти не на север к Перекрестку, а в Таурахо.$B$BТы, |3-6($c), $gмог:могла; бы мне помочь.$B$BУбей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах.' WHERE `ID` = 899 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Быть может, тебе знакома мука неопределенности, а может, и нет. Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть. Быть может, мне стоило идти не на север к Перекрестку, а в Таурахо.$B$BТы, |3-6($c), $gмог:могла; бы мне помочь.$B$BУбей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах.' AS BINARY)));
