UPDATE `quest_template_locale` SET `QuestDescription` = 'Друиды в Пещерах Стенаний, Друиды Клыка поражены порчей. Когда-то они были частью ордена друидов давшего обет исцелить Степи, но теперь они хотят перекроить эти земли в соответствии со своими извращенными мечтаниями.$B$BУ Друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни и в Степях снова воцарится мир.$B$BИди, $n,  и разыщи их укрытия в Пещерах Стенаний.' WHERE `ID` = 914 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Друиды в Пещерах Стенаний, Друиды Клыка поражены порчей. Когда-то они были частью ордена друидов давшего обет исцелить Степи, но теперь они хотят перекроить эти земли в соответствии со своими извращенными мечтаниями.$B$BУ Друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни и в Степях снова воцарится мир.$B$BИди, $n,  и разыщи их укрытия в Пещерах Стенаний.' AS BINARY)));
