UPDATE `quest_template_locale` SET `QuestDescription` = 'Ты $gсделал:сделала; мне много добра, $n. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что еще.$B$BГарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин\'Зилу.$B$BОн будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место.' WHERE `ID` = 1060 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Ты $gсделал:сделала; мне много добра, $n. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что еще.$B$BГарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин\'Зилу.$B$BОн будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место.' AS BINARY)));
