UPDATE `quest_template_locale` SET `QuestDescription` = 'Цели у Наралекса были самые благие.$b$bНаш лидер стремился впасть в Изумрудный сон, и  вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так.$b$bМечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры.$b$bВ то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей.$b$bОтправляйся туда, $n. и уничтожь порченое семя.' WHERE `ID` = 1487 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Цели у Наралекса были самые благие.$b$bНаш лидер стремился впасть в Изумрудный сон, и  вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так.$b$bМечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры.$b$bВ то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей.$b$bОтправляйся туда, $n. и уничтожь порченое семя.' AS BINARY)));
