UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Тебе следует усвоить еще пару вещей. Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно. Отблеск Благодати лежит на тебе – это видят и друзья, и враги.$B$BКроме того, когда ты наберешься опыта, тебе надо будет овладеть новыми способностями. Вот тут я тебе и пригожусь. Когда ты почувствуешь, себя $Gготовым:готовой;, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать. Удачи тебе, |3-6($c)!' WHERE `ID` = 3101 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('Тебе следует усвоить еще пару вещей. Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно. Отблеск Благодати лежит на тебе – это видят и друзья, и враги.$B$BКроме того, когда ты наберешься опыта, тебе надо будет овладеть новыми способностями. Вот тут я тебе и пригожусь. Когда ты почувствуешь, себя $Gготовым:готовой;, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать. Удачи тебе, |3-6($c)!' AS BINARY)));
UPDATE `quest_request_items_locale` SET `CompletionText` = 'Наконец-то! Вот мы и встретились, $gбрат мой:сестра моя;. Приветствую тебя в Североземье! Это место будет твоим домом, пока ты не усвоишь азы нашего дела, но знай, что Штормград недалеко, и рано или поздно твой путь приведет тебя туда. Ну а пока наберись терпения... рыцарь Серебряной Длани.' WHERE `ID` = 3101 AND `locale` = 'ruRU' AND (NOT (CAST(`CompletionText` AS BINARY) <=> CAST('Наконец-то! Вот мы и встретились, $gбрат мой:сестра моя;. Приветствую тебя в Североземье! Это место будет твоим домом, пока ты не усвоишь азы нашего дела, но знай, что Штормград недалеко, и рано или поздно твой путь приведет тебя туда. Ну а пока наберись терпения... рыцарь Серебряной Длани.' AS BINARY)));
