UPDATE `quest_template_locale` SET `QuestDescription` = 'Мы бились в маленьком лагере тауренов и разделились в бою – на нее наседали разом три иглогрива Вздыбленной Щетины. Силы были неравны. Я отвлек на себя очень многих и увидел, что набежали новые враги и одолевают ее. Впав в ярость, я бросился на врагов, но они с легкостью одержали надо мной верх.$B$BЯ пришел в себя и увидел, что таурен-друид ухаживает за мной, – он набрел на меня на Золотом пути.$B$BПрошу тебя, |3-6($c), узнай что-нибудь о моей жене.' WHERE `ID` = 4921 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Мы бились в маленьком лагере тауренов и разделились в бою – на нее наседали разом три иглогрива Вздыбленной Щетины. Силы были неравны. Я отвлек на себя очень многих и увидел, что набежали новые враги и одолевают ее. Впав в ярость, я бросился на врагов, но они с легкостью одержали надо мной верх.$B$BЯ пришел в себя и увидел, что таурен-друид ухаживает за мной, – он набрел на меня на Золотом пути.$B$BПрошу тебя, |3-6($c), узнай что-нибудь о моей жене.' AS BINARY)));
