UPDATE `quest_template_locale` SET `QuestDescription` = 'Твоя сила производит впечатление, |3-6($c), а интерес к охоте дает надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьезнее.$B$BОрда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса. Если ты $gготов:готова; проявить себя в непознанных еще землях, обратись к Сенани Громосерд на заставе Расщепленного Древа. Она находится к северу от тропы из Степей.' WHERE `ID` = 6382 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Твоя сила производит впечатление, |3-6($c), а интерес к охоте дает надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьезнее.$B$BОрда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса. Если ты $gготов:готова; проявить себя в непознанных еще землях, обратись к Сенани Громосерд на заставе Расщепленного Древа. Она находится к северу от тропы из Степей.' AS BINARY)));
