UPDATE `quest_template_locale` SET `QuestDescription` = 'Зло рыщет по побережью, |3-6($r).$B$BЗдесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощенный морем. Разрушенный и почти забытый.$B$BТеперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись.$B$BПринеси мне 20 их голов! Загони наг назад, в глубины моря!' WHERE `ID` = 6442 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Зло рыщет по побережью, |3-6($r).$B$BЗдесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощенный морем. Разрушенный и почти забытый.$B$BТеперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись.$B$BПринеси мне 20 их голов! Загони наг назад, в глубины моря!' AS BINARY)));
